const clientItems = $('Split Into Items').all();
const out = [];
$input.all().forEach((item, idx) => {
  const client = (clientItems[idx] || {}).json || {};
  const msgs = item.json.messages || [];
  msgs.forEach(m => out.push({ json: { client_id: client.client_id, client_name: client.client_name, client_email: client.client_email, message_id: m.id } }));
});
return out;

function b64urlDecode(s) { if (!s) return ''; const b64 = s.replace(/-/g, '+').replace(/_/g, '/'); return Buffer.from(b64, 'base64').toString('utf-8'); }
function walk(part, out) { if (!part) return; if (part.mimeType === 'text/plain' && part.body && part.body.data) { out.push(b64urlDecode(part.body.data)); return; } if (part.parts) { part.parts.forEach(p => walk(p, out)); return; } if (part.body && part.body.data && (!part.mimeType || part.mimeType.indexOf('text/') === 0)) { out.push(b64urlDecode(part.body.data)); } }
const msg = $json;
const out = [];
walk(msg.payload, out);
let text = out.join('\n\n').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim();
if (!text) text = '(no readable body)';
const headers = (msg.payload && msg.payload.headers) || [];
const subject = (headers.find(h => h.name === 'Subject') || {}).value || '(no subject)';
const from = (headers.find(h => h.name === 'From') || {}).value || '';
const client = $('Flatten Messages').item.json;
return { json: { client_id: client.client_id, client_name: client.client_name, client_email: client.client_email, message_id: client.message_id, subject, from, body: text.slice(0, 6000) } };

