let text = '';
try { text = $json.output[0].content[0].text; } catch (e) { text = '{}'; }
text = text.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let parsed = {};
try { parsed = JSON.parse(text); } catch (e) { parsed = {}; }
const newItems = Array.isArray(parsed.new_items) ? parsed.new_items : [];
const resolvedIds = Array.isArray(parsed.resolved_ids) ? parsed.resolved_ids : [];
const src = $('Extract Message Text').item.json;
const rows = newItems.filter(a => a && a.name).map(a => ({ client_id: src.client_id, name: String(a.name).slice(0, 120), note: a.note ? String(a.note).slice(0, 300) : null, source_doc_id: src.message_id, status: 'pending' }));
const resolved = resolvedIds.filter(r => r && r.id).map(r => ({ action_id: r.id, evidence: r.evidence ? String(r.evidence).slice(0, 300) : null }));
return { json: { rows, resolved, rowCount: rows.length, resolvedCount: resolved.length } };

const out = [];
$input.all().forEach(item => { (item.json.resolved || []).forEach(r => out.push({ json: { action_id: r.action_id, evidence: r.evidence } })); });
return out;

